Value.Calculation:
epSQLExecute (
	"SELECT Nivelacija.Status, Nivelacija.DatumNivelacije, Nivelacija.BrojNivelacije," &
	"  Nivelacija.NacinIzmjene, Nivelacija.AzurirajStandardnuCijenu" &
	" FROM Nivelacija WHERE Nivelacija.PrimaryKey = ?" ;
	"useSQLResult=rs_hdr" ;
	$nivelacijaId
)

epSQLExecute (
	"SELECT StavkeNivelacije.PrimaryKey, StavkeNivelacije.ForeignKeyStavkaPrimkeID," &
	"  StavkeNivelacije.NacinIzmjene, StavkeNivelacije.NovaMPCijena," &
	"  StavkeNivelacije.NoviPDVPostotak, StavkeNivelacije.ForeignKeyArtikalID" &
	" FROM StavkeNivelacije" &
	" WHERE StavkeNivelacije.ForeignKeyNivelacijaID = ?" &
	" ORDER BY StavkeNivelacije.RedniBroj" ;
	"useSQLResult=rs_lines" ;
	$nivelacijaId
)

JSONSetElement ( $lines ; "[" & $i & "]" ;
	JSONSetElement ( "{}" ;
		[ "stavkaId" ; epSQLResult ( $i ; 0 ; "rs_lines" ) ; JSONString ] ;
		[ "batchId" ; epSQLResult ( $i ; 1 ; "rs_lines" ) ; JSONString ] ;
		[ "nacin" ; epSQLResult ( $i ; 2 ; "rs_lines" ) ; JSONString ] ;
		[ "ciljBruto" ; GetAsNumber ( epSQLResult ( $i ; 3 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "noviPDV" ; GetAsNumber ( epSQLResult ( $i ; 4 ; "rs_lines" ) ) ; JSONNumber ] ;
		[ "artikalId" ; epSQLResult ( $i ; 5 ; "rs_lines" ) ; JSONString ]
	) ;
	JSONObject
)

Step.Calculation:
Let ( [
		~batch = epSQLResult ( $i ; 0 ; "rs_chr" ) ;
		~inDoc = GetAsNumber ( JSONGetElement ( $batchSet ; ~batch ) ) = 1 ;
		~vazi = GetAsDate ( epSQLResult ( $i ; 1 ; "rs_chr" ) ) ;
		~tip = GetAsNumber ( epSQLResult ( $i ; 2 ; "rs_chr" ) ) ;
		~izvor = epSQLResult ( $i ; 3 ; "rs_chr" )
	];

	~inDoc and ( ~vazi > $docDate or ( ~vazi = $docDate and ~tip = 2 and ~izvor > $broj ) )
)

Value.Calculation:
Response_AddError ( "NIV_CHRONOLOGY_CONFLICT" ;
	ValueCount ( $conflicts ) & " serija već ima noviji cjenovni događaj od " & $broj & "." ;
	"DatumNivelacije" ;
	JSONSetElement ( "{}" ; "konflikti" ; Substitute ( $conflicts ; Char ( 13 ) ; " | " ) ; JSONString ) ; "" )

JSONSetElement ( $asof ; $batchId ;
	JSONSetElement ( "{}" ;
		[ "bruto" ; GetAsNumber ( epSQLResult ( $i ; 1 ; "rs_evt" ) ) ; JSONNumber ] ;
		[ "pdv" ; GetAsNumber ( epSQLResult ( $i ; 2 ; "rs_evt" ) ) ; JSONNumber ] ;
		[ "nabavna" ; GetAsNumber ( epSQLResult ( $i ; 3 ; "rs_evt" ) ) ; JSONNumber ] ;
		[ "primljeno" ; GetAsNumber ( epSQLResult ( $i ; 4 ; "rs_evt" ) ) ; JSONNumber ]
	) ;
	JSONObject
)

JSONSetElement ( $cons ; $batchId ;
	GetAsNumber ( JSONGetElement ( $cons ; $batchId ) ) + $sign * GetAsNumber ( epSQLResult ( $i ; 2 ; "rs_con" ) ) ;
	JSONNumber
)

JSONSetElement ( $consAfter ; $batchId ;
	GetAsNumber ( JSONGetElement ( $consAfter ; $batchId ) ) + Abs ( GetAsNumber ( epSQLResult ( $i ; 2 ; "rs_con" ) ) ) ;
	JSONNumber
)

JSONSetElement ( $calc ; "[" & $i & "]" ;
	JSONSetElement ( "{}" ;
		[ "stavkaId" ; JSONGetElement ( $row ; "stavkaId" ) ; JSONString ] ;
		[ "batchId" ; $batchId ; JSONString ] ;
		[ "artikalId" ; JSONGetElement ( $row ; "artikalId" ) ; JSONString ] ;
		[ "kolicina" ; $kolicina ; JSONNumber ] ;
		[ "nacin" ; $nacin ; JSONString ] ;
		[ "staraBruto" ; $staraBruto ; JSONNumber ] ;
		[ "staraNetoJed" ; $staraNetoJed ; JSONNumber ] ;
		[ "stariPDV" ; $stariPDV ; JSONNumber ] ;
		[ "nabavna" ; $nabavna ; JSONNumber ] ;
		[ "novaBruto" ; $novaBruto ; JSONNumber ] ;
		[ "novaNetoJed" ; $novaNetoJed ; JSONNumber ] ;
		[ "noviPDV" ; $noviPDV ; JSONNumber ] ;
		[ "staraVrij" ; $staraVrij ; JSONNumber ] ;
		[ "staraVrijNeto" ; $staraVrijNeto ; JSONNumber ] ;
		[ "novaVrij" ; $novaVrij ; JSONNumber ] ;
		[ "novaVrijNeto" ; $novaVrijNeto ; JSONNumber ] ;
		[ "razlika" ; $razlika ; JSONNumber ] ;
		[ "razlikaRUC" ; $razlikaRUC ; JSONNumber ] ;
		[ "razlikaPDV" ; $razlikaPDV ; JSONNumber ]
	) ;
	JSONObject
)

Response_AddError ( "NIV_BACKDATE_PRICE_CHANGE" ;
	ValueCount ( $violations ) & " stavki mijenja cijenu serije koja je prodavana nakon " & $docDate & "." ;
	"DatumNivelacije" ;
	JSONSetElement ( "{}" ; "stavke" ; Substitute ( $violations ; Char ( 13 ) ; " | " ) ; JSONString ) ; "" )

Response_AddError ( "NIV_IDENTITY_VIOLATION" ;
	ValueCount ( $identityFails ) & " stavki ne zadovoljava razlika = RUC + PDV." ;
	"RazlikaVrijednost" ;
	JSONSetElement ( "{}" ; "stavke" ; Substitute ( $identityFails ; Char ( 13 ) ; " | " ) ; JSONString ) ; "" )

epSQLExecute (
	"UPDATE StavkeNivelacije SET" &
	"  KolicinaNaStanju = ?, NabavnaCijenaEfektivna = ?, NacinIzmjene = ?," &
	"  StaraMPCijena = ?, StaraMPCijenaBezPDV = ?, StariPDVPostotak = ?," &
	"  StariPDVIznos = ?, StariRUCIznos = ?," &
	"  NovaMPCijena = ?, NovaMPCijenaBezPDV = ?, NoviPDVPostotak = ?," &
	"  NoviPDVIznos = ?, NoviRUCIznos = ?," &
	"  StaraVrijednost = ?, StaraVrijednostBezPDV = ?," &
	"  NovaVrijednost = ?, NovaVrijednostBezPDV = ?," &
	"  RazlikaVrijednost = ?, RazlikaRUC = ?, RazlikaPDV = ?" &
	" WHERE PrimaryKey = ?" ;
	"" ;
	GetAsNumber ( JSONGetElement ( $c ; "kolicina" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "nabavna" ) ) ;
	JSONGetElement ( $c ; "nacin" ) ;
	GetAsNumber ( JSONGetElement ( $c ; "staraBruto" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "staraNetoJed" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "stariPDV" ) ) ;
	Round ( GetAsNumber ( JSONGetElement ( $c ; "staraBruto" ) ) - GetAsNumber ( JSONGetElement ( $c ; "staraNetoJed" ) ) ; 4 ) ;
	Round ( GetAsNumber ( JSONGetElement ( $c ; "staraNetoJed" ) ) - GetAsNumber ( JSONGetElement ( $c ; "nabavna" ) ) ; 4 ) ;
	GetAsNumber ( JSONGetElement ( $c ; "novaBruto" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "novaNetoJed" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "noviPDV" ) ) ;
	Round ( GetAsNumber ( JSONGetElement ( $c ; "novaBruto" ) ) - GetAsNumber ( JSONGetElement ( $c ; "novaNetoJed" ) ) ; 4 ) ;
	Round ( GetAsNumber ( JSONGetElement ( $c ; "novaNetoJed" ) ) - GetAsNumber ( JSONGetElement ( $c ; "nabavna" ) ) ; 4 ) ;
	GetAsNumber ( JSONGetElement ( $c ; "staraVrij" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "staraVrijNeto" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "novaVrij" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "novaVrijNeto" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "razlika" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "razlikaRUC" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "razlikaPDV" ) ) ;
	JSONGetElement ( $c ; "stavkaId" )
)

epSQLExecute (
	"UPDATE StavkePrimke SET ProdajnaCijena = ?, PDVPostotak_Trenutni = ?" &
	" WHERE PrimaryKey = ?" ;
	"" ;
	GetAsNumber ( JSONGetElement ( $c ; "novaBruto" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "noviPDV" ) ) ;
	JSONGetElement ( $c ; "batchId" )
)

epSQLExecute (
	"INSERT INTO CijeneStavki" &
	" ( PrimaryKey, KeyEvent, ForeignKeyStavkaPrimkeID, ForeignKeyArtikalID, VaziOd," &
	"   TipPrioritet, Cijena, PDVPostotak, NabavnaCijenaEfektivna, IzvorTip, IzvorID, IzvorBroj )" &
	" VALUES ( ?, ?, ?, ?, " & epSQLQuoteDate ( $docDate ) & ", 2, ?, ?, ?, ?, ?, ? )" ;
	"" ;
	TSID ;
	JSONGetElement ( $c ; "batchId" ) & "|Nivelacija|" & $nivelacijaId ;
	JSONGetElement ( $c ; "batchId" ) ;
	JSONGetElement ( $c ; "artikalId" ) ;
	GetAsNumber ( JSONGetElement ( $c ; "novaBruto" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "noviPDV" ) ) ;
	GetAsNumber ( JSONGetElement ( $c ; "nabavna" ) ) ;
	"Nivelacija" ;
	$nivelacijaId ;
	$broj
)

epSQLExecute (
	"UPDATE Artikli SET ProdajnaCijena_Standardna = ? WHERE PrimaryKey = ?" ;
	"" ;
	GetAsNumber ( JSONGetElement ( $c ; "novaBruto" ) ) ;
	JSONGetElement ( $c ; "artikalId" )
)

epSQLExecute (
	"UPDATE Nivelacija SET" &
	"  Status = ?, DatumKnjizenja = ?," &
	"  UkupnoStaraVrijednost = ?, UkupnoNovaVrijednost = ?, UkupnoRazlika = ?," &
	"  UkupnoStaraVrijednostBezPDV = ?, UkupnoNovaVrijednostBezPDV = ?," &
	"  UkupnoRazlikaRUC = ?, UkupnoRazlikaPDV = ?" &
	" WHERE PrimaryKey = ?" ;
	"" ;
	"Knjižena" ;
	Get ( CurrentHostTimeStamp ) ;
	$tS ; $tN ; $tR ; $tSn ; $tNn ; $tRUC ; $tPDV ;
	$nivelacijaId
)

Response_SetData ( JSONSetElement ( "{}" ;
	[ "nivelacijaId" ; $nivelacijaId ; JSONString ] ;
	[ "brojNivelacije" ; $broj ; JSONString ] ;
	[ "brojStavki" ; $lineCount ; JSONNumber ] ;
	[ "ukupnoStaraVrijednost" ; $tS ; JSONNumber ] ;
	[ "ukupnoNovaVrijednost" ; $tN ; JSONNumber ] ;
	[ "ukupnoRazlika" ; $tR ; JSONNumber ] ;
	[ "ukupnoStaraVrijednostBezPDV" ; $tSn ; JSONNumber ] ;
	[ "ukupnoNovaVrijednostBezPDV" ; $tNn ; JSONNumber ] ;
	[ "ukupnoRazlikaRUC" ; $tRUC ; JSONNumber ] ;
	[ "ukupnoRazlikaPDV" ; $tPDV ; JSONNumber ]
) )
